# Title: Lucky Numbers Sieve
# Finds "lucky numbers" using a sieving process similar to the Sieve of Eratosthenes.
# Lucky numbers are generated by iteratively removing every nth element from a list,
# creating a fascinating sequence with properties similar to primes but via a different method.

def find_lucky_numbers(limit):
    """Generate lucky numbers up to limit using the lucky number sieve."""
    # Start with all odd numbers (first filtering removes evens)
    numbers = list(range(1, limit + 1, 2))
    
    i = 1  # Start from second element (index 1, value 3)
    while i < len(numbers) and numbers[i] <= len(numbers):
        step = numbers[i]
        # Remove every step-th element
        numbers = [numbers[j] for j in range(len(numbers)) if (j + 1) % step != 0]
        i += 1
    
    return numbers

def sieve_of_eratosthenes(limit):
    """Generate primes up to limit for comparison."""
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, limit + 1, i):
                is_prime[j] = False
    
    return [i for i in range(limit + 1) if is_prime[i]]

def main():
    limit = 200
    lucky = find_lucky_numbers(limit)
    primes = sieve_of_eratosthenes(limit)
    
    print("=" * 60)
    print("LUCKY NUMBERS vs PRIMES: A Tale of Two Sequences")
    print("=" * 60)
    print()
    
    print(f"Lucky numbers up to {limit}:")
    print(lucky)
    print(f"Count: {len(lucky)}")
    print()
    
    print(f"Prime numbers up to {limit}:")
    print(primes)
    print(f"Count: {len(primes)}")
    print()
    
    lucky_set = set(lucky)
    prime_set = set(primes)
    
    both = lucky_set & prime_set
    only_lucky = lucky_set - prime_set
    only_prime = prime_set - lucky_set
    
    print("Interesting overlaps:")
    print(f"Both lucky AND prime: {sorted(both)}")
    print(f"Lucky but NOT prime: {sorted(only_lucky)}")
    print(f"Prime but NOT lucky: {sorted(only_prime)}")
    print()
    
    # Find twin lucky numbers (differ by 2)
    twin_lucky = [n for n in lucky if n + 2 in lucky_set]
    print(f"Twin lucky numbers (differ by 2): {twin_lucky}")
    print()
    
    # Density comparison
    print(f"Lucky density: {len(lucky) / limit * 100:.1f}%")
    print(f"Prime density: {len(primes) / limit * 100:.1f}%")

if __name__ == "__main__":
    main()
